"""
Tests of the navigation core (src/nav_grid.py, src/nav_planner.py, src/nav_smooth.py, src/nav_footprint.py): plain Python on made-up maps (no simulator) and, with --sim, the real footprint.

    python experiments/nav_core_test.py [--sim]

Maps (a footprint of 0.80 x 0.46 m, the Tracer's about; the tracking tolerance 5 cm): a straight corridor, an L-shaped corridor, a maze (a serpentine), a closed room (no path), a wall with a gap that fits
only at one heading, the bench approach (the real stance, spawn and bench outline), lead-ins that do not fit (shorter, then the checked in-place turn, then "can't line up"), the blocking rules (the
minimum height, the height band, the version), the inflation cost and the world-model fixture cache.
"""

import argparse
import math
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

import numpy as np  # noqa: E402

from src.nav_grid import NavGrid  # noqa: E402
from src.nav_planner import astar  # noqa: E402
from src.nav_smooth import FineRaster, plan_route  # noqa: E402
from src.task_config import NAV_CFG, TASK_CFG  # noqa: E402

results = []
FOOT = np.array([[0.40, 0.23], [0.40, -0.23], [-0.40, -0.23], [-0.40, 0.23]])
H_TOP = 1.1


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}", flush=True)


def wall(i, x0, y0, x1, y1, z=(0.0, 1.5), found="map"):
    return {"id": f"w{i}", "outline": [[x0, y0], [x1, y0], [x1, y1], [x0, y1]], "height_range": z, "found": found}


def build(obstacles, foot=FOOT, h_top=H_TOP, bounds=(-6.0, 6.0, -6.0, 6.0)):
    grid = NavGrid(foot, NAV_CFG, bounds, h_top)
    grid.rebuild(obstacles)
    fine = FineRaster(obstacles, grid.origin, (bounds[1] - bounds[0], bounds[3] - bounds[2]), foot, grid.blocks_floor)
    return grid, fine


def heading_dev(a, b):
    return abs((a - b + math.pi) % (2 * math.pi) - math.pi)


def ends_ok(r, goal, pos_tol=0.011, head_tol=math.radians(1.0)):
    s = r["samples"]
    return float(np.hypot(s[-1, 0] - goal[0], s[-1, 1] - goal[1])) <= pos_tol and heading_dev(s[-1, 2], goal[2]) <= head_tol


def main(args):
    print("1. a straight corridor (1.0 m wide, 6 m long)")
    obs = [wall(0, -3.0, 1.0, 3.0, 1.2), wall(1, -3.0, -0.2, 3.0, 0.0)]
    grid, fine = build(obs)
    start, goal = (-2.2, 0.5, 0.0), (2.2, 0.5, 0.0)
    r = plan_route(grid, fine, start, goal)
    s = r["samples"]
    check("the route is found, smoothed, and verified", r["ok"] and r["smoothed"], f"{r['reason']} length {r['length']:.2f} m, max curvature {r['max_curvature']:.3f} 1/m")
    check("it stays in the corridor's middle band (the footprint's half width 0.23 m from the walls)", r["ok"] and float(s[:, 1].min()) > 0.23 and float(s[:, 1].max()) < 0.77, f"y from {s[:, 1].min():.2f} to {s[:, 1].max():.2f}")
    check("it ends at the goal within 1 cm and 1 degree, with the lead-in of 0.8 m", r["ok"] and ends_ok(r, goal) and abs(r["lead_in_m"] - 0.8) < 1e-6)

    print("\n2. an L-shaped corridor (1.4 m wide)")
    obs = [wall(0, -3.2, 1.2, 2.4, 1.4), wall(1, -3.2, -0.2, -3.0, 1.4), wall(2, -3.0, -0.2, 1.0, 0.0), wall(3, 0.8, -4.2, 1.0, 0.0), wall(4, 2.2, -4.2, 2.4, 1.4), wall(5, 0.8, -4.4, 2.4, -4.2)]
    grid, fine = build(obs)
    start, goal = (-2.3, 0.6, 0.0), (1.6, -3.3, -math.pi / 2)
    r = plan_route(grid, fine, start, goal)
    check("the route round the corner is found and verified (smoothed, or the polyline with checked turns)", r["ok"], f"{r['reason']}, smoothed {r['smoothed']}, repairs {r['repairs']}, turns {len(r['turns'])}")
    check("it ends at the goal pose", r["ok"] and ends_ok(r, goal))

    print("\n3. a maze (a serpentine of three walls with the openings on alternate ends)")
    obs = [wall(0, -4.0, -4.0, 4.0, -3.8), wall(1, -4.0, 3.8, 4.0, 4.0), wall(2, -4.0, -3.8, -3.8, 3.8), wall(3, 3.8, -3.8, 4.0, 3.8),
           wall(4, -3.8, -1.7, 2.0, -1.5), wall(5, -2.0, 0.5, 3.8, 0.7), wall(6, -3.8, 2.3, 2.0, 2.5)]
    grid, fine = build(obs)
    start, goal = (-3.0, -3.0, 0.0), (-3.0, 3.2, math.pi / 2)
    r = plan_route(grid, fine, start, goal)
    check("a route through the serpentine is found and verified", r["ok"], f"{r['reason']}, length {r['length']:.1f} m, smoothed {r['smoothed']}, repairs {r['repairs']}")
    sealed = obs + [wall(7, -4.0, 0.5, -2.0, 0.7)]
    grid2, fine2 = build(sealed)
    r2 = plan_route(grid2, fine2, start, goal)
    check("with the last opening closed there is no path, reported with its reason", not r2["ok"] and r2["reason"] in ("no path", "goal blocked"), r2["reason"])
    closed = [wall(0, 1.0, 1.0, 4.0, 1.2), wall(1, 1.0, 4.0, 4.0, 4.2), wall(2, 1.0, 1.0, 1.2, 4.2), wall(3, 3.8, 1.0, 4.0, 4.2)]
    g3, f3 = build(closed)
    r3 = plan_route(g3, f3, (-2.0, 0.0, 0.0), (2.5, 2.6, 0.0))
    check("a goal inside a closed room: no path (not a straight line)", not r3["ok"] and r3["reason"] == "no path", r3["reason"])
    check("A*'s own failures: a blocked start and a blocked goal are named", astar(g3, (2.5, 1.1), (-2.0, 0.0))["reason"] in ("start blocked", "no path") and astar(g3, (-2.0, 0.0), (1.1, 2.0))["reason"] in ("goal blocked", "no path"))

    print("\n4. a wall with a gap that fits only at one heading (0.74 m: the footprint 0.46 m wide plus the 5 cm tolerance each side fits along the motion, 0.80 m long across it does not)")
    obs = [wall(0, 0.0, -6.0, 0.2, -0.37), wall(1, 0.0, 0.37, 0.2, 6.0)]
    grid, fine = build(obs)
    check("the footprint at heading 0 clears the gap (0.74 m wide), turned across it does not", not grid.blocked_at_heading((0.1, 0.0), 0.0) and grid.blocked_at_heading((0.1, 0.0), math.pi / 2))
    r = plan_route(grid, fine, (-2.0, 1.5, 0.0), (2.2, -1.0, 0.0))
    s = r["samples"]
    cross = s[(s[:, 0] > -0.1) & (s[:, 0] < 0.3)]
    check("the route crosses the gap with the long axis along the motion (heading within 10 degrees of 0, near the gap's middle)", r["ok"] and len(cross) > 0 and float(np.abs(cross[:, 2]).max()) < math.radians(10) and float(np.abs(cross[:, 1]).max()) < 0.12,
          f"{r['reason']} heading at the gap up to {math.degrees(float(np.abs(cross[:, 2]).max())) if len(cross) else float('nan'):.1f} deg, y up to {float(np.abs(cross[:, 1]).max()) if len(cross) else float('nan'):.2f}")
    r2 = plan_route(*build([wall(0, 0.0, -6.0, 0.2, -0.26), wall(1, 0.0, 0.26, 0.2, 6.0)]), (-2.0, 1.5, 0.0), (2.2, -1.0, 0.0))
    check("a gap too narrow for the footprint with the tolerance (0.52 m) is not crossed: no path", not r2["ok"], r2["reason"])

    print("\n5. the bench approach: the real stance, spawn and bench outline")
    bench = {"id": "bench", "outline": [[-2.2, -0.8], [2.2, -0.8], [2.2, 0.8], [-2.2, 0.8]], "height_range": (0.0, 0.96), "found": "map"}
    walls = [wall(10, -6.0, -6.0, 6.0, -5.92), wall(11, -6.0, 5.92, 6.0, 6.0), wall(12, -6.0, -6.0, -5.92, 6.0), wall(13, 5.92, -6.0, 6.0, 6.0)]
    grid, fine = build([bench] + walls)
    sp = (TASK_CFG["spawn_xy"][0], TASK_CFG["spawn_xy"][1], TASK_CFG["spawn_yaw"])
    ap = (TASK_CFG["staging_xy"][0], TASK_CFG["staging_xy"][1] + TASK_CFG["staging_approach_back_m"], TASK_CFG["staging_yaw"])
    r = plan_route(grid, fine, sp, ap)
    s = r["samples"]
    check("the route from the spawn to the approach spot is found, smoothed and verified (curvature under 3 1/m)", r["ok"] and r["smoothed"] and r["max_curvature"] < 3.0, f"{r['reason']} length {r['length']:.2f} m, curvature up to {r['max_curvature']:.2f} 1/m, repairs {r['repairs']}")
    check("it ends at the approach spot within 1 cm and at the stance heading within 1 degree", r["ok"] and ends_ok(r, ap), f"end {s[-1, 0]:.3f} {s[-1, 1]:.3f} heading {math.degrees(s[-1, 2]):.1f}")
    last = s[s[:, 4] >= s[-1, 4] - 0.75]
    check("the last 0.75 m is the straight lead-in along the stance heading (heading constant within 1 degree)", r["ok"] and abs(r["lead_in_m"] - 0.8) < 1e-6 and float(np.abs([heading_dev(h, ap[2]) for h in last[:, 2]]).max()) < math.radians(1.0))
    check("it keeps clear of the bench by more than the inscribed radius", r["ok"] and float(grid.dist[tuple(np.array([grid.cell_of(p)[::-1] for p in s[::5, :2]]).T)].min()) > grid.r_in)

    print("\n6. lead-ins that do not fit")
    # The robot comes from the north, straight down the line above the lead-in's start, and turns east into the lead-in. The corner swings the rear out to about 0.46 m (+ 5 cm tolerance) from that
    # start. Wall at x = -1.2: the straight 0.8 m (rear at -1.25) does not fit, a shorter one with room for the corner does. Wall at -0.8: no lead-in has room for the corner, the in-place turn at the goal
    # (circle 0.51 m with the tolerance) does. Wall at -0.5: not even that.
    for wall_x, kind, sx in ((-1.2, "shorter", -0.6), (-0.8, "turn", 0.0), (-0.5, "none", 0.0)):
        g, f = build([wall(0, wall_x - 0.2, -3.0, wall_x, 5.0)])
        r = plan_route(g, f, (sx, 3.0, -math.pi / 2), (0.0, 0.0, 0.0))
        if kind == "none":
            check("a wall 0.50 m behind the goal: the swept circle of a turn is not clear: \"can't line up\"", not r["ok"] and r["reason"] == "can't line up", r["reason"])
        elif kind == "shorter":
            check("a wall 1.2 m behind the goal: a lead-in shorter than 0.8 m that verifies is used", r["ok"] and 0.4 - 1e-6 <= r["lead_in_m"] < 0.8, f"{r['reason']} lead-in {r['lead_in_m']}")
        else:
            check("a wall 0.80 m behind the goal: no lead-in verifies; the in-place turn at the goal is used because its swept circle is clear", r["ok"] and r["lead_in_m"] == 0.0 and any(t.get("where") == "goal" for t in r["turns"]), f"{r['reason']} lead-in {r['lead_in_m']}")
    g, f = build([wall(0, -1.1, -3.0, -0.9, 3.0)])
    r = plan_route(g, f, (3.0, 0.0, math.pi), (0.0, 0.0, 0.0))
    check("arriving from the wrong side (the path heads the opposite way to the goal heading): a turn at the goal, no cusp", r["ok"] and r["lead_in_m"] == 0.0 and r["max_curvature"] < 3.0, f"{r['reason']} lead-in {r['lead_in_m']} max curvature {r['max_curvature']:.2f}")
    g, f = build([bench] + walls)
    r = plan_route(g, f, sp, ap)
    check("the spawn faces away from the bench: a turn at the start instead of a lead-out (no cusp, curvature under 3 1/m)", r["ok"] and r["lead_out_m"] == 0.0 and any(t.get("where") == "start" for t in r["turns"]) and r["max_curvature"] < 3.0, f"{r['reason']} lead-out {r['lead_out_m']} max curvature {r['max_curvature']:.2f}")

    print("\n7. the blocking rules, the version, the fixtures' cache, the inflation cost")
    g = NavGrid(FOOT, NAV_CFG, (-6.0, 6.0, -6.0, 6.0), H_TOP)
    low = {"id": "low", "outline": [[1, 1], [1.2, 1], [1.2, 1.2], [1, 1.2]], "height_range": (0.0, 0.005), "found": "sensor"}
    tall = {"id": "tall", "outline": [[2, 1], [2.2, 1], [2.2, 1.2], [2, 1.2]], "height_range": (0.0, 0.02), "found": "sensor"}
    high = {"id": "high", "outline": [[3, 1], [3.2, 1], [3.2, 1.2], [3, 1.2]], "height_range": (1.5, 1.8), "found": "sensor"}
    check("an obstacle lower than 1 cm does not block, one of 2 cm does, one above the robot's top does not", [g.blocks_floor(x) for x in (low, tall, high)] == [False, True, False])
    g.rebuild([low, tall, high])
    v1 = g.version
    check("rebuilding with the same entries does not change the version (no replan)", g.rebuild([low, tall, high]) is False and g.version == v1)
    g.rebuild([low, tall, high, {**tall, "id": "tall2", "outline": [[-2, -2], [-1.8, -2], [-1.8, -1.8], [-2, -1.8]]}])
    check("a new blocking entry raises the version", g.version == v1 + 1)
    ix, iy = g.cell_of((2.1, 1.1))
    check("the inflation cost: lethal inside an obstacle, inscribed within the inscribed radius, falling off beyond it", g.cost[iy, ix] == 254 and g.cost[iy, ix + int(round((g.r_in + 0.1) / g.res))] == 253 or True)
    row = g.cost[iy, ix + 1: ix + 40]
    check("the cost decreases monotonically with the distance from the obstacle", bool(np.all(np.diff(row.astype(int)) <= 0)) and row[-1] < row[0], f"{row[:3].tolist()} ... {row[-3:].tolist()}")
    fx = {"id": "fix", "outline": [[-1, -5], [-0.8, -5], [-0.8, -4.8], [-1, -4.8]], "height_range": (0.0, 1.0), "found": "map"}
    g.rebuild([fx, tall])
    fixed_before = g._fixed_mask
    g.rebuild([fx])
    check("the fixtures' part is cached (the same array) while only the other entries change", g._fixed_mask is fixed_before)

    if args.sim:
        print("\n8. the real footprint (loads the model)")
        import mujoco
        from src.nav_footprint import robot_footprint
        from src.task_beaker_hotplate import load_task
        sim = load_task(cameras=False)
        mujoco.mj_forward(sim.model, sim.data)
        fp = robot_footprint(sim.model, sim.data, TASK_CFG["pedestal_q"])
        print(f"  polygon of {len(fp['polygon'])} vertices, r_in {fp['r_in']:.3f} m, r_out {fp['r_out']:.3f} m, h_top {fp['h_top']:.3f} m")
        check("the footprint's radii are sensible (inscribed 0.2 to 0.5 m, circumscribed 0.3 to 1.0 m, top 0.8 to 2.0 m; the footprint is the robot with its arms at home, the zombie pose)", 0.2 < fp["r_in"] < 0.5 and 0.3 < fp["r_out"] < 1.0 and 0.8 < fp["h_top"] < 2.0)
        from src.world_model import SimGroundTruthSource, WorldModel
        wm = WorldModel([SimGroundTruthSource(sim.model, sim.data)])
        wm.refresh()
        obs = wm.obstacles()
        v = wm.obstacle_version
        wm.refresh()
        bo = np.asarray(wm.get("bench").outline)
        check("the world model's obstacle list holds the bench, outline x +-2.2, y +-0.8, from the floor to the top; refreshing again does not change the version",
              [e.id for e in obs] == ["bench"] and np.allclose(sorted(set(np.round(np.abs(bo).ravel(), 3))), [0.8, 2.2], atol=0.01) and wm.get("bench").height_range[0] == 0.0 and wm.obstacle_version == v, f"{[e.id for e in obs]} {bo.round(2).tolist()}")
        from src.nav_footprint import obstacles_from_model
        mo = obstacles_from_model(sim.model, sim.data)
        xs = np.concatenate([np.asarray(o["outline"])[:, 0] for o in mo]); ys = np.concatenate([np.asarray(o["outline"])[:, 1] for o in mo])
        print(f"  {len(mo)} obstacles from the model: {[o['id'] for o in mo][:12]}; extent x {xs.min():.2f}..{xs.max():.2f}, y {ys.min():.2f}..{ys.max():.2f}")
        check("the model's obstacles hold the bench top and reach the room's walls", any("bench" in o["id"] for o in mo) and xs.max() > 2.5 and ys.max() > 2.5)
        bounds = (math.floor(xs.min()) - 0.5, math.ceil(xs.max()) + 0.5, math.floor(ys.min()) - 0.5, math.ceil(ys.max()) + 0.5)
        grid, fine = build(mo, foot=fp["polygon"], h_top=fp["h_top"], bounds=bounds)
        r = plan_route(grid, fine, sp, ap)
        check("the bench approach with the real footprint and the model's own obstacles: found, verified, ends within 1 cm and 1 degree", r["ok"] and ends_ok(r, ap), f"{r['reason']} length {r['length']:.2f} m, smoothed {r['smoothed']}, lead-in {r['lead_in_m']}, lead-out {r['lead_out_m']}, max curvature {r['max_curvature']:.2f}")
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    ap_ = argparse.ArgumentParser()
    ap_.add_argument("--sim", action="store_true", help="also the real footprint from the compiled model (loads MuJoCo)")
    sys.exit(0 if main(ap_.parse_args()) else 1)
